def update_pheromone(tau, tours, lens, rho):
    new = (1.0 - rho) * tau                                      # випаровування
    for g, L in zip(tours, lens):
        t = np.concatenate(([0], g, [0])).astype(int)            # з вокзалу і назад, ребра напрямлені
        new[t[:-1], t[1:]] += 1.0 / L
    return new
